<template>
<section class="capture-composer" @paste="pasteImages">
<div class="page-heading"><h1 tabindex="-1">新增紀錄</h1><button @click="cancel">取消</button></div>
<p v-if="entryContext?.symbol" class="local-state">從 {{ entryContext.symbol }} {{ entryContext.exchange||'' }} 的紀錄新增<span v-if="entryContext.report_label"> · 引用研究 {{ entryContext.report_label }}</span>。保存時仍需明確核對獨立部位或追加觀測。</p><ol class="intake-steps" aria-label="新增進度"><li :aria-current="!parsed?'step':undefined">準備資料</li><li :aria-current="parsed&&!preview?'step':undefined">核對內容</li><li :aria-current="preview?'step':undefined">保存</li></ol>
<nav class="method-choices" aria-label="新增方式"><button :aria-pressed="method==='capture'" @click="method='capture'">從截圖整理</button><button :aria-pressed="method==='manual'" @click="method='manual'">手動記錄</button><button :aria-pressed="method==='csv'" @click="method='csv'">CSV</button></nav>
<template v-if="method==='csv'"><CsvImport/></template>
<template v-else>
<div v-if="problem" ref="errorSummary" class="canonical-alert" tabindex="-1" role="alert"><p>{{ problem }}</p><a :href="parsed?'#candidate-main':'#candidate-input'" @click="focusInput">返回整理結果修正</a><a v-if="problem.includes('完整備份')" href="?workspace=management">到資料管理還原</a></div>
<template v-if="!parsed">
<template v-if="method==='capture'"><h2>在對話整理，回來核對</h2><p>在目前 ChatGPT 對話貼上截圖。AI 整理在對話中完成，這裡負責核對與保存。</p><button @click="showGuide=true;copyGuide()">取得截圖整理指引</button><details v-if="showGuide" open><summary>可複製到目前對話</summary><label>整理格式要求<textarea :value="captureGuide" readonly rows="5"/></label></details><p v-if="copyMessage" role="status">{{ copyMessage }}</p><label>選擇整理結果檔（JSON，最多 1 MB）<input type="file" accept=".json,application/json" @change="readPackage"/></label><details open><summary>貼上整理結果</summary><label for="candidate-input">整理結果<textarea id="candidate-input" v-model="raw" rows="6" spellcheck="false" aria-describedby="package-help"/></label><p id="package-help" class="muted">未知資料可以保留；完整備份請到資料管理還原。</p></details><button class="primary" :disabled="working||!raw.trim()" @click="parse">核對整理結果</button></template>
<template v-else><h2>手動記錄畫面或成交證據</h2><p>未知欄位可留空。完整股票／現貨成交可使用下方既有成交表單。</p><div class="form-grid"><label>資料種類<select v-model="manual.kind"><option value="snapshot">持倉畫面</option><option value="execution_evidence">成交證據</option></select></label><label>標的<input v-model="manual.symbol" maxlength="32"/></label><label>商品<select v-model="manual.product"><option v-for="(label,key) in products" :key="key" :value="key">{{ label }}</option></select></label><label>方向<select v-model="manual.direction"><option value="unknown">未知</option><option value="long">做多</option><option value="short">做空</option></select></label><label>交易所<input v-model="manual.exchange" maxlength="100"/></label><label>日期（未知可留空）<input type="date" v-model="manual.date"/></label><label>買賣<select v-model="manual.side"><option value="BUY">買入</option><option value="SELL">賣出</option></select></label><label>數量（未知可留空）<input type="number" min="0" step="any" v-model="manual.quantity"/></label><label>價格（未知可留空）<input type="number" min="0" step="any" v-model="manual.price"/></label><label>價格幣別<input v-model="manual.currency" maxlength="8"/></label></div><label>備註<textarea v-model="manual.note" rows="3" maxlength="3000"/></label><button class="primary" @click="manualPreview">核對手動紀錄</button><details><summary>完整股票／現貨成交</summary><TradeRecords ref="manualRecords" mode="manual" :active="true"/></details></template>
</template>
<section v-if="savedBatch" class="intake-receipt"><h2>{{ savedBatch.status==='applied'?'這批整理結果已保存':'這批整理結果已撤回' }}</h2><p>原批次核對收據已保留，這次沒有重複新增。</p><p v-if="savedBatch.status==='withdrawn'">如需復原，請到資料管理核對原批次後明確復原。</p><button @click="finishSaved">返回原紀錄</button><a v-if="savedBatch.status==='withdrawn'" href="?workspace=management">到資料管理查看原批次</a></section>
<label v-if="!savedBatch">加入本機截圖比對（只在目前分頁預覽）<input type="file" accept="image/png,image/jpeg,image/webp" multiple @change="readImages"/></label><p v-if="images.length" class="muted">{{ images.length }} 張本機預覽，沒有傳送圖片。</p>
<template v-if="parsed&&!savedBatch">
<div class="button-row"><button :disabled="index<=0" @click="index--">上一筆</button><span>第 {{ index+1 }} / {{ rows.length }} 筆</span><button :disabled="index>=rows.length-1" @click="index++">下一筆</button><button @click="preview=null">繼續核對</button><button @click="resetPackage">回準備資料</button></div>
<div class="candidate-layout" v-if="row">
<aside class="source-preview"><h2>來源核對</h2><article v-for="s in rowSources" :key="s.id"><h3>{{ s.name }}</h3><img v-if="matchingImage(s)" :src="matchingImage(s).url" :alt="s.name+' 本機核對預覽'"/><p v-else>原圖未在此分頁開啟。可重新選擇原圖比對。</p><p class="muted">{{ s.sha256?'原檔雜湊已提供；相符只證明同檔':'原檔雜湊未知，來源尚未核對' }}</p></article></aside>
<div class="candidate-fields"><h2>{{ row.extracted_fields.symbol||row.extracted_fields.instrument?.symbol }}</h2><p>{{ row.kind==='snapshot'?'持倉畫面':'成交證據 · 僅留存' }}</p>
<label class="check-label"><input type="checkbox" v-model="row.selected" @change="changed"/>保存這筆紀錄</label>
<div class="form-grid"><label>標的<input id="candidate-main" v-model="rowInstrument.symbol" @input="changed" maxlength="32"/></label><label>商品<select v-model="rowInstrument.product" @change="changed"><option v-for="(label,key) in products" :key="key" :value="key">{{ label }}</option></select></label><label>方向<select v-model="rowInstrument.direction" @change="changed"><option value="unknown">未提供</option><option value="long">做多</option><option value="short">做空</option></select></label><label>交易所<input :value="rowInstrument.exchange||''" @input="rowInstrument.exchange=$event.target.value||null;changed()" maxlength="100"/></label><label>日期（未知留空）<input type="date" :value="row.extracted_fields.captured_date||row.extracted_fields.event_date||''" @input="setDate($event.target.value)"/></label></div>
<template v-if="row.kind==='snapshot'"><div class="form-grid"><label v-for="(field,key) in row.extracted_fields.fields" :key="key">{{ snapshotFields[key] }} · {{ field.unit }}<input type="number" step="any" :value="field.value" @input="setNumber(key,$event.target.value)"/></label></div><p class="muted">數量未提供時不反推；畫面投資額不是名目曝險。</p><label>補充數值<select v-model="addField"><option value="">選擇原畫面欄位</option><option v-for="(label,key) in snapshotFields" :key="key" :value="key">{{ label }}</option></select></label><div v-if="addField" class="button-row"><label>數值<input type="number" step="any" v-model="addValue"/></label><label>原單位<select v-model="addUnit"><option v-for="u in units" :key="u">{{ u }}</option></select></label><button @click="appendField">加入欄位</button></div></template>
<template v-else><div class="form-grid"><label>買賣<select v-model="row.extracted_fields.side" @change="changed"><option value="BUY">買入</option><option value="SELL">賣出</option></select></label><label v-for="key in ['quantity','price','fees']" :key="key">{{ {quantity:'數量',price:'成交價',fees:'費用'}[key] }}（未知留空）<input type="number" step="any" :value="row.extracted_fields[key]??''" @input="row.extracted_fields[key]=$event.target.value===''?null:Number($event.target.value);changed()"/></label><label>幣別<input :value="row.extracted_fields.currency||''" @input="row.extracted_fields.currency=$event.target.value||null;changed()" maxlength="8"/></label><label>原画面時間（未知留空）<input :value="row.extracted_fields.local_datetime||''" @input="row.extracted_fields.local_datetime=$event.target.value||null;changed()" placeholder="YYYY-MM-DD HH:MM:SS"/></label><label>時區（未知留空）<input :value="row.extracted_fields.timezone||''" @input="row.extracted_fields.timezone=$event.target.value||null;changed()" maxlength="100"/></label></div></template>
<label>備註<textarea v-model="row.extracted_fields.note" @input="changed" maxlength="3000" rows="3"/></label>
<label>部位與重複處理<select v-model="row.choice" @change="changed"><option value="new">建立獨立新部位</option><option value="update">追加到既有部位</option><option v-if="row.kind==='snapshot'" value="merge_source">同一觀測，合併來源</option><option value="skip">略過這筆</option></select></label>
<label v-if="row.choice==='update'">選擇既有部位<select v-model="row.target" @change="changed"><option value="">請選擇</option><option v-for="p in positions.filter(p=>p.origin!=='ledger')" :key="p.id" :value="p.id">{{ p.instrument.symbol }} · {{ p.instrument.exchange||'交易所未知' }} · {{ p.instrument.direction }} · {{ p.id.slice(-14) }}</option></select></label>
<label v-if="['merge_source','skip'].includes(row.choice)">對應既有觀測<select v-model="row.target" @change="changed"><option value="">未指定</option><option v-for="s in state.snapshots||[]" :key="s.id" :value="s.id">{{ s.symbol }} · {{ s.exchange||'交易所未知' }} · {{ s.id.slice(-14) }}</option></select></label>
<details v-if="row.possible.length" open><summary>同標的既有畫面，請核對是否重複</summary><article v-for="s in possibleSnapshots" :key="s.id"><strong>{{ s.symbol }} · {{ s.exchange||'交易所未知' }} · {{ s.direction }}</strong><p>{{ s.captured_date||'日期未確認' }} · {{ s.fields.leverage?.value||'未知' }} x</p><p v-for="(f,k) in s.fields" :key="k">{{ snapshotFields[k] }}：{{ f.value }} {{ f.unit }}</p></article></details>
<label v-if="['update','merge_source'].includes(row.choice)" class="check-label"><input type="checkbox" v-model="row.identity_confirmed" @change="changed"/>我已核對來源與差異，確認屬於同一{{ row.choice==='update'?'部位':'觀測，保留既有數值' }}</label>
<label v-if="row.choice==='update'&&row.kind==='snapshot'" class="check-label"><input type="checkbox" v-model="row.adopt" @change="changed"/>將這張明確選為摘要採用畫面（未知日期不代表最新）</label>
<label class="check-label"><input type="checkbox" v-model="row.confirmed" @change="preview=null"/>已核對這筆內容，未知欄位保留未知</label>
</div></div>
<div class="intake-savebar"><p>已選 {{ rows.filter(r=>r.selected&&r.choice!=='skip').length }} 筆 · {{ rows.filter(r=>r.selected&&r.choice!=='skip'&&!r.confirmed).length }} 筆需核對</p><template v-if="preview"><p>新增 {{ preview.counts.new }} 個部位／追加 {{ preview.counts.update }} 筆／成交證據 {{ preview.counts.evidence }} 筆／略過 {{ preview.counts.skip }} 筆</p><p v-if="stale" role="alert">其他分頁已更新資料。請載入最新後重新核對。</p><button :disabled="busy||working||stale" class="primary" @click="savePreview">{{ busy?'保存中…':'保存所選 '+rows.filter(r=>r.selected&&r.choice!=='skip').length+' 筆' }}</button></template><button :disabled="busy||working" @click="prepare">{{ stale?'載入最新後重新核對':'預覽本次新增' }}</button></div>
</template></template>
</section>
</template>
<script setup>
import {computed,ref,watch,onUnmounted,nextTick} from 'vue';import CsvImport from './CsvImport.vue';import TradeRecords from './TradeRecords.vue';
import {parseCandidatePackage,candidateChoices,buildIntakeDelta,savedIntakeReceipt,captureGuide} from './capture-intake.mjs';import {projectPositions,copy,digest} from './decision-workspace.mjs';import {snapshotFields} from './snapshot-core.mjs';
const props=defineProps({state:Object,scope:String,revision:Number,busy:Boolean,initialMethod:String,reload:Function,entryContext:Object});const emit=defineEmits(['save','cancel']);
const method=ref(props.initialMethod||'capture'),raw=ref(''),parsed=ref(null),rows=ref([]),index=ref(0),images=ref([]),problem=ref(''),working=ref(false),preview=ref(null),errorSummary=ref(null),showGuide=ref(false),copyMessage=ref(''),addField=ref(''),addValue=ref(''),addUnit=ref('USDT');const savedBatch=ref(null),base=ref(null);let sequence=0,saveLock=false;
const products={perpetual:'永續',spot:'現貨',stock_token:'股票代幣',bot:'機器人',unknown:'未提供'},units=['USDT','TWD','USD','%','x','token','contract','unit'];
const manual=ref({kind:'snapshot',symbol:props.entryContext?.symbol||'',product:props.entryContext?.product||'unknown',direction:props.entryContext?.direction||'unknown',exchange:props.entryContext?.exchange||'',date:'',quantity:'',price:'',currency:'',side:'BUY',note:''});
const manualRecords=ref(null);
const initialManual=JSON.stringify(manual.value);
const row=computed(()=>rows.value[index.value]),positions=computed(()=>projectPositions(props.state)),rowInstrument=computed(()=>row.value?.kind==='snapshot'?row.value.extracted_fields:row.value?.extracted_fields.instrument),rowSources=computed(()=>parsed.value?.package.sources.filter(s=>row.value?.source_refs.includes(s.id))||[]),possibleSnapshots=computed(()=>(props.state.snapshots||[]).filter(s=>row.value?.possible.includes(s.id))),stale=computed(()=>base.value&&(base.value.expectedScope!==props.scope||base.value.expectedRevision!==props.revision));
const dirty=computed(()=>!!raw.value.trim()||!!parsed.value||JSON.stringify(manual.value)!==initialManual||!!images.value.length||!!manualRecords.value?.dirty);defineExpose({dirty});
watch(()=>props.scope,(v,p)=>{if(p&&p!==v){clear();manual.value={kind:'snapshot',symbol:'',product:'unknown',direction:'unknown',exchange:'',date:'',quantity:'',price:'',currency:'',side:'BUY',note:''};}});
function clear(){sequence++;raw.value='';parsed.value=null;savedBatch.value=null;rows.value=[];preview.value=null;images.value.forEach(i=>URL.revokeObjectURL(i.url));images.value=[];base.value=null;problem.value='';}
function changed(){preview.value=null;row.value.confirmed=false;}
function setDate(v){row.value.extracted_fields[row.value.kind==='snapshot'?'captured_date':'event_date']=v||null;changed();}
function setNumber(k,v){if(v==='')delete row.value.extracted_fields.fields[k];else row.value.extracted_fields.fields[k].value=Number(v);changed();}
function appendField(){if(addField.value&&addValue.value!==''){row.value.extracted_fields.fields[addField.value]={value:Number(addValue.value),unit:addUnit.value};addField.value='';addValue.value='';changed();}}
function matchingImage(s){return images.value.find(i=>s.sha256?i.sha256===s.sha256:i.name===s.name);}
async function issue(e){problem.value=(e.path?e.path+'：':'')+e.message;if(e.path){const found=rows.value.findIndex(r=>r.id===e.path);if(found>=0)index.value=found;}await nextTick();errorSummary.value?.focus();}
async function copyGuide(){try{await navigator.clipboard.writeText(captureGuide);copyMessage.value='指引已複製，請貼到目前對話並附上截圖。';}catch{copyMessage.value='可從下方選取並複製指引。';}}
async function parse(){if(working.value)return;const seq=++sequence,scope=props.scope;working.value=true;problem.value='';try{const result=await parseCandidatePackage(raw.value);if(seq!==sequence||scope!==props.scope)return;parsed.value=result;savedBatch.value=savedIntakeReceipt(props.state,result);rows.value=candidateChoices(result,props.state);base.value={expectedScope:props.scope,expectedRevision:props.revision};index.value=0;preview.value=null;}catch(e){await issue(e);}finally{working.value=false;}}
async function readPackage(e){const file=e.target.files[0],scope=props.scope,seq=sequence;if(!file)return;try{if(file.size>1000000)throw new Error('整理結果超過 1 MB。');const value=await file.text();if(scope===props.scope&&seq===sequence){raw.value=value;await parse();}}catch(e){await issue(e);}finally{e.target.value='';}}
async function readImages(event){const files=event.target.files||event;if(!files.length)return;const seq=sequence,scope=props.scope;try{if(images.value.length+files.length>20||[...files].reduce((n,f)=>n+f.size,images.value.reduce((n,i)=>n+i.size,0))>50000000)throw new Error('最多 20 張、合計 50 MB，請拆批核對。');for(const file of files){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10000000)throw new Error('每張最多 10 MB，只支援 PNG、JPEG、WebP。');const bytes=await file.arrayBuffer(),hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(v=>v.toString(16).padStart(2,'0')).join(''),url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();}catch{URL.revokeObjectURL(url);throw new Error('這張圖片無法解碼，請重新選擇有效原圖。');}if(seq!==sequence||scope!==props.scope){URL.revokeObjectURL(url);return;}images.value.push({name:file.name,size:file.size,sha256:hash,url});}}catch(e){await issue(e);}finally{if(event.target)event.target.value='';}}
function pasteImages(e){const files=[...e.clipboardData.items].filter(i=>i.kind==='file').map(i=>i.getAsFile());if(files.length){e.preventDefault();readImages(files);}}
async function manualPreview(){const m=manual.value,nullable=v=>v===''?null:Number(v),inst={symbol:m.symbol.trim().toUpperCase(),product:m.product,direction:m.direction,exchange:m.exchange.trim()||null};const fields=m.kind==='snapshot'?{...inst,captured_date:m.date||null,screen_time:null,fields:{...(m.quantity!==''?{quantity:{value:Number(m.quantity),unit:'unit'}}:{}),...(m.price!==''?{average_price:{value:Number(m.price),unit:m.currency}}:{})},note:m.note,observed_history:[]}:{instrument:inst,event_date:m.date||null,side:m.side,quantity:nullable(m.quantity),price:nullable(m.price),fees:null,currency:m.currency||null,local_datetime:null,timezone:null,note:m.note};raw.value=JSON.stringify({format:'investment-capture-candidates-v1',sources:[{id:'manual',name:'手動紀錄',sha256:null,library_file_id:null}],candidates:[{id:crypto.randomUUID(),kind:m.kind,source_refs:['manual'],extracted_fields:fields}]});await parse();}
async function prepare(){if(working.value)return;working.value=true;problem.value='';const seq=sequence,scope=props.scope;try{if(stale.value){await props.reload();await nextTick();}if(seq!==sequence||scope!==props.scope)return;const result=await buildIntakeDelta(props.state,parsed.value,copy(rows.value));if(seq!==sequence||scope!==props.scope)return;base.value={expectedScope:props.scope,expectedRevision:props.revision};preview.value=result;}catch(e){await issue(e);}finally{working.value=false;}}
function finishSaved(){emit('save',{already_applied:true,receipt:savedBatch.value},base.value,ok=>{if(ok)clear();});}
function savePreview(){if(saveLock||props.busy||stale.value||!preview.value)return;saveLock=true;emit('save',preview.value,base.value,ok=>{saveLock=false;if(ok)clear();});}
function resetPackage(){if(confirm('回到準備資料會保留原始整理文字，放棄本次核對修改。')){parsed.value=null;preview.value=null;rows.value=[];}}
function cancel(){if(!dirty.value||confirm('放棄這個分頁尚未保存的草稿？')){clear();emit('cancel');}}
function focusInput(){nextTick(()=>document.getElementById(parsed.value?'candidate-main':'candidate-input')?.focus());}
onUnmounted(clear);
</script>
